"""Build a qualification snapshot and a provisional, label-blind acquisition queue."""
import json,hashlib,html
from pathlib import Path
from neurofusion.qualification import acquisition_queue,qualification_gates
root=Path(__file__).resolve().parents[1];out=root/'experiments/ucsf-qualification-001';out.mkdir(exist_ok=False)
read=lambda rel:json.loads((root/rel).read_text(encoding='utf-8'))
inputs={'confirmation':'experiments/ucsf-clipping-confirmation-001/summary.json','verification':'experiments/ucsf-clipping-confirmation-001/verification.json','inventory':'experiments/pdgm-cohort-separation-001/candidate-inventory.json','partition':'experiments/ucsf-specialist-plan-001/partitions.json','target':'configs/ucsf_target_contract.json','review':'experiments/pdgm-alignment-gallery-001/summary.json'}
data={k:read(v) for k,v in inputs.items()}
development={r['patient_id'] for r in data['partition']['records']}
queue=acquisition_queue(data['inventory'],development)
for row in queue['records']:
    directory=root/'data/raw/ucsf-pdgm-v5'/row['exam_id']
    row['local_files_present']=[name for name in row['files'] if (directory/name).is_file()]
    row['status']='present_requires_verification' if row['local_files_present'] else 'not_acquired'
(out/'acquisition-queue.json').write_text(json.dumps(queue,indent=2)+'\n',encoding='utf-8')
evidence={'reproducibility_verified':data['verification'].get('new_native_masks_reproduced_on_reload')==12 and data['verification'].get('new_checkpoints_hash_checked')==15,'all_seeds_passed':data['confirmation']['all_seeds_passed'],'target_contract_signed':False,'version_specific_mapping_confirmed':data['target']['version_specific_mapping_confirmed'],'independence_verified':False,'all_external_files_verified':False,'expert_review_complete':False,'evaluation_protocol_frozen':False,'independent_performance_passed':False,'candidate_integration_verified':False,'release_review_signed':False}
status=qualification_gates(evidence)
requirements={
'development_reproducibility':('complete','Hash-pinned checkpoints, source, splits and reproduced predictions.','Completed: 15 new checkpoint hashes and 12 reproduced masks.'),
'development_performance':('failed','All predefined checks pass per seed; explicitly count empty outputs, poor-overlap patients and false-positive volume.','Clipping confirmation failed the false-positive check for seeds 43 and 44.'),
 'target_contract':('pending','Freeze supported modality, numeric target union, exclusions and claim wording. Clinical compartment names additionally require version-specific label confirmation.','Numeric foreground engineering target exists; qualification contract is not signed/frozen.'),
 'cohort_independence':('pending','Audit patient identities, source mapping, duplicates and all development exposure; document limitations.','192 metadata candidates are not 192 verified independent patients. Same UCSF source is not external-site validation.'),
 'acquisition_integrity':('pending','Acquire approved provisional pairs; verify source/license/version, checksums, geometry, labels and immutable inventory.','20-patient acquisition queue prepared without labels or model scores; no new files downloaded.'),
 'expert_alignment_review':('pending','Record whole-volume image/annotation alignment review and exclusions with reviewer identity, date and reason.','Existing pilot expert reviews: 0/20. This cannot be replaced by automated checks.'),
 'frozen_evaluation_protocol':('pending','Before inference, fix cohort, checkpoint hash, preprocessing, threshold, metrics, confidence intervals, exclusion rules and acceptance criteria.','Do not freeze a model that has not qualified, or select thresholds on this cohort.'),
 'independent_performance':('pending','Run the frozen protocol once; report every eligible patient, uncertainty, subgroup limits and all failures.','Repeated use of four development patients is not independent evaluation.'),
 'application_integration':('pending','Only after qualification, add a registry entry and test supported volume inputs, original-grid outputs, limits and rollback.','Current viewer still uses BRISC tumor models and the DWI stroke baseline; UCSF remains a research artifact.'),
 'release_review':('pending','Review intended research use, data handling, licensing, failure reporting and deployment tests before release.','A research release review does not authorize clinical diagnosis.')}
for gate in status['gates']:
    gate['status'],gate['completion_criteria'],gate['current_evidence']=requirements[gate['id']]
status.update({'evidence':evidence,'queue_patients':queue['selected_patients'],'eligible_metadata_patients':queue['eligible_patients'],'queue_acquired_pairs':sum(len(r['local_files_present'])==2 for r in queue['records']),'next_action':'Verify source access and acquire/audit the provisional queue without model inference; keep cohort unfrozen.','clinical_claims':False})
(out/'summary.json').write_text(json.dumps(status,indent=2)+'\n',encoding='utf-8')
(out/'provenance.json').write_text(json.dumps({v:hashlib.sha256((root/v).read_bytes()).hexdigest() for v in list(inputs.values())+['src/neurofusion/qualification.py','scripts/build_ucsf_qualification.py']},indent=2),encoding='utf-8')
(out/'build-script.py').write_bytes(Path(__file__).read_bytes())
rows=''.join(f'<tr><td>{html.escape(g["id"].replace("_"," "))}</td><td>{g["status"]}</td><td>{html.escape(g["completion_criteria"])}</td><td>{html.escape(g["current_evidence"])}</td></tr>' for g in status['gates'])
patients=''.join(f'<tr><td>{r["patient_id"]}</td><td>{r["exam_id"]}</td><td>{r["status"]}</td></tr>' for r in queue['records'])
(out/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NeuroFusion qualification and remaining work</title><style>body{font:16px system-ui;background:#101b2b;color:#ecf3fb;max-width:1200px;margin:30px auto;padding:20px}td,th{padding:12px;border-bottom:1px solid #456;text-align:left;vertical-align:top}a{color:#80ded0}.scroll{overflow:auto}progress{width:100%;height:26px}.note{border-left:3px solid #efbc64;padding-left:15px}</style><h1>Qualification and remaining work</h1><h2>This planning stage: 4/4 complete</h2><progress max="4" value="4" aria-label="Planning deliverables: four of four"></progress><p>Evidence audit, qualification gates, provisional acquisition queue, and published progress view.</p>'''+f'<h2>UCSF research qualification: {status["passed"]}/{status["total"]} gates passed</h2><progress max="{status["total"]}" value="{status["passed"]}" aria-label="Research qualification gates"></progress><p class="note">This is a qualification checklist, not whole-project completion or diagnostic accuracy. Planning completion does not satisfy the gates. The historical overall 86% was an informal estimate and is not presented as measured progress.</p><div class="scroll"><table><tr><th>Gate</th><th>Status</th><th>Required evidence</th><th>Current state</th></tr>'+rows+'</table></div><h2>Provisional acquisition queue</h2><p>20 patients chosen by a fixed identity hash from 192 metadata candidates, excluding every development patient and recorded BraTS mapping. No model scores or labels used. No new data downloaded. Absence of a mapping does not prove independence; a held-out UCSF cohort also does not establish external-site performance.</p><details><summary>View queued patients</summary><table><tr><th>Patient</th><th>Baseline exam</th><th>Local status</th></tr>'+patients+'</table></details><h2>Broader project work still open</h2><ul><li>Additional planned datasets and specialists, including CT and EEG branches.</li><li>Multi-specialist fusion, uncertainty and qualification for each supported task.</li><li>Independent evaluation, expert review and release/deployment readiness.</li></ul><p>Existing tumor and stroke baselines and the local research viewer are implemented; this does not mean every planned brain condition is supported.</p><p><a href="summary.json">Qualification evidence</a> · <a href="acquisition-queue.json">Acquisition queue</a> · <a href="provenance.json">Source checksums</a></p></html>',encoding='utf-8')
print(json.dumps({'gates_passed':status['passed'],'gates_total':status['total'],'queued_patients':len(queue['records']),'local_pairs':status['queue_acquired_pairs']},indent=2))
